const $=id=>document.getElementById(id),KEY='watchlyst-simple-v1';let items=[],filter='All titles',editing=null;const statuses=['All titles','Watching','Planned','Completed','On hold'];const colors=['#314533','#49402e','#283c49','#4c3038','#3b3550'];
function notify(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,2600)}
try{items=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(items)||!items.every(valid))throw Error()}catch(e){$('storageWarning').hidden=false;$('storageWarning').textContent='Saved data could not be loaded. Import a backup or add titles to begin.';items=[]}
function safeURL(s){if(typeof s!=='string')return false;if(!s)return true;try{return ['http:','https:'].includes(new URL(s).protocol)}catch(e){return false}}
function valid(x){return x&&typeof x.id==='string'&&typeof x.title==='string'&&x.title.trim()&&['Series','Anime','Movie'].includes(x.type)&&typeof x.genre==='string'&&typeof x.notes==='string'&&safeURL(x.url||'')&&Number.isInteger(x.watched)&&x.watched>=0&&x.watched<=100000&&(x.total===null||(Number.isInteger(x.total)&&x.total>0&&x.total<=100000&&x.watched<=x.total))&&statuses.slice(1).includes(x.status)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(items));return true}catch(e){$('storageWarning').hidden=false;$('storageWarning').textContent='Browser saving is unavailable. Export a backup before closing this page.';return false}}
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function render(){const counts=[items.length,items.filter(x=>x.status==='Watching').length,items.filter(x=>x.status==='Completed').length,items.reduce((s,x)=>s+x.watched,0)];$('stats').replaceChildren(...counts.map((n,i)=>{const d=el('div','stat');d.append(el('strong','',String(n).padStart(2,'0')),el('span','',['Titles in your lyst','Currently watching','Stories completed','Episodes watched'][i]));return d}));$('tabs').replaceChildren(...statuses.map(s=>{const b=el('button','tab'+(s===filter?' active':''),s);b.setAttribute('aria-pressed',s===filter);b.onclick=()=>{filter=s;render()};return b}));const q=$('search').value.toLowerCase();const visible=items.filter(x=>(filter==='All titles'||x.status===filter)&&(x.title+' '+x.genre).toLowerCase().includes(q)).sort((a,b)=>(b.updated||0)-(a.updated||0));$('grid').replaceChildren();if(!visible.length){const d=el('div','empty');d.append(el('h2','',items.length?'No matching stories.':'Your next favourite starts here.'),el('p','',items.length?'Try another search or filter.':'Add a movie, anime, or series and keep track of every episode.'));if(!items.length){const b=el('button','btn','＋ Add your first title');b.onclick=()=>open();d.append(b)}$('grid').append(d)}visible.forEach(x=>{const card=el('article','card'),art=el('div','art');art.style.background=colors[[...x.title].reduce((s,c)=>s+c.charCodeAt(0),0)%colors.length];art.append(el('span','badge',x.type+' / '+(x.genre||'Unsorted')),el('b','',x.title));const c=el('div','content'),meta=el('div','meta');meta.append(el('span','',x.status.toUpperCase()),el('span','',x.total===null?'ONGOING':x.type==='Movie'?'FILM':x.total+' EPISODES'));c.append(meta,el('h2','',x.title));if(x.notes)c.append(el('p','small',x.notes));if(x.url){const link=el('a','watch-link','Open watch link ↗');link.href=x.url;link.target='_blank';link.rel='noopener noreferrer';c.append(link)}const label=el('div','progress-label');label.append(el('span','',x.total===null?'Ongoing · total unknown':x.watched===x.total?'All caught up':x.watched===0?'A new story awaits':'Picking up where you left off'),el('span','',x.total===null?x.watched+' watched':x.watched+' / '+x.total));const bar=el('div','bar'+(x.total===null?' ongoing':'')),fill=el('i');fill.style.width=x.total===null?'0%':(x.watched/x.total*100)+'%';bar.append(fill);c.append(label,bar);const actions=el('div','actions'),plus=el('button','btn',x.status==='Completed'?'✓ Completed':x.type==='Movie'?'✓ Mark watched':'+1 Episode');plus.disabled=x.status==='Completed'||x.watched>=100000;plus.onclick=()=>{x.watched++;x.status=x.total!==null&&x.watched===x.total?'Completed':'Watching';x.updated=Date.now();save();render()};const edit=el('button','edit','Edit');edit.setAttribute('aria-label','Edit '+x.title);edit.onclick=()=>open(x);actions.append(plus,edit);c.append(actions);card.append(art,c);$('grid').append(card)})}
function open(x){editing=x?.id||null;$('form').reset();$('dialogTitle').textContent=x?'Edit your story':'Add a new story';for(const k of ['title','type','genre','watched','total','status','notes','url'])if(x)$(k).value=x[k]??'';$('ongoing').checked=!!x&&x.total===null;syncOngoing();$('delete').hidden=!x;$('dialog').showModal();$('title').focus()}
$('add').onclick=()=>open();$('cancel').onclick=()=>$('dialog').close();$('search').oninput=render;function syncOngoing(){$('total').disabled=$('ongoing').checked;$('total').required=!$('ongoing').checked;$('ongoing').disabled=$('type').value==='Movie'}
$('ongoing').onchange=syncOngoing;$('type').onchange=()=>{if($('type').value==='Movie'){$('ongoing').checked=false;$('total').value=1;$('watched').value=Math.min(1,Number($('watched').value))}syncOngoing()};$('form').onsubmit=e=>{e.preventDefault();const watched=Number($('watched').value),total=$('ongoing').checked?null:Number($('total').value);if(total!==null&&watched>total){$('watched').setCustomValidity('Watched episodes cannot exceed the total.');$('watched').reportValidity();return}const x={id:editing||crypto.randomUUID(),title:$('title').value.trim(),type:$('type').value,genre:$('genre').value.trim(),watched,total,status:$('status').value,notes:$('notes').value.trim(),url:$('url').value.trim(),updated:Date.now()};if(!x.title){$('title').setCustomValidity('Enter a title.');$('title').reportValidity();return}if(!safeURL(x.url)){$('url').setCustomValidity('Use a full http:// or https:// URL.');$('url').reportValidity();return}if(total!==null){if(x.status==='Completed')x.watched=total;else if(watched===total)x.status='Completed';}if(editing)items=items.map(i=>i.id===editing?x:i);else items.push(x);const saved=save();$('dialog').close();render();notify(saved?'Your lyst is up to date':'Added for this session — export a backup')};$('watched').oninput=()=>$('watched').setCustomValidity('');$('total').oninput=()=>$('watched').setCustomValidity('');$('url').oninput=()=>$('url').setCustomValidity('');$('title').oninput=()=>$('title').setCustomValidity('');$('delete').onclick=()=>{if(confirm('Delete this title from your lyst?')){items=items.filter(x=>x.id!==editing);save();$('dialog').close();render()}};$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(items,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download='watchlyst-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
render();

const columns=['ID','Title','Type','Genre','Episodes watched','Total episodes','Ongoing','Status','URL','Notes','Updated'];
function exportRows(list){return list.map(x=>[x.id,x.title,x.type,x.genre,x.watched,x.total===null?'':x.total,x.total===null?'Yes':'No',x.status,x.url||'',x.notes,new Date(x.updated||Date.now()).toISOString()])}
function excelBook(list){const wb=XLSX.utils.book_new(),ws=XLSX.utils.aoa_to_sheet([columns,...exportRows(list)]);ws['!cols']=[{wch:38},{wch:32},{wch:12},{wch:20},{wch:19},{wch:18},{wch:12},{wch:14},{wch:55},{wch:55},{wch:26}];ws['!autofilter']={ref:ws['!ref']};XLSX.utils.book_append_sheet(wb,ws,'WatchLyst');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([
['WatchLyst Excel database','Instructions'],
['Editing','Edit the WatchLyst sheet, then import the .xlsx file into the site.'],
['Required column','Title. Other columns have defaults for new rows. Keep column headers.'],
['ID','Keep IDs to update existing records. Leave blank for new titles.'],
['Type','Series, Anime, or Movie. Default: Series.'],
['Ongoing','Yes = no episode total. A blank Total episodes also means ongoing.'],
['Episodes watched','Whole number, 0 to 100000. Default: 0.'],
['Total episodes','Positive whole number >= Episodes watched, or blank for ongoing.'],
['Status','Watching, Planned, Completed, or On hold. Default: Watching.'],
['URL','Optional full http:// or https:// address.'],
['Updated','ISO date/time. Blank or missing = import time.'],
['Import','Preview, then Merge titles or Replace list. Invalid rows cancel the entire import.'],
['Storage','The site saves in this browser. Excel is a manual portable database, not live sync.']
]),'Read me');return wb}
$('exportExcel').onclick=()=>{try{XLSX.writeFile(excelBook(items),'WatchLyst.xlsx',{compression:true});notify('Excel database exported')}catch(e){notify('Excel export failed. Try the JSON backup.')}};
function parseExcelRows(rows){if(!rows.length)throw Error('The WatchLyst sheet is empty.');const norm=s=>String(s??'').trim().toLowerCase().replace(/[^a-z0-9]/g,'');const headers=rows[0].map(norm);if(!headers.includes('title'))throw Error('The first row must contain a Title column.');if(new Set(headers.filter(Boolean)).size!==headers.filter(Boolean).length)throw Error('Duplicate column headers.');const get=(row,name)=>row[headers.indexOf(norm(name))]??'';const text=(row,name)=>String(get(row,name)).trim();const out=[];rows.slice(1).forEach((row,index)=>{if(row.every(v=>v===''||v===null||v===undefined))return;const fail=msg=>{throw Error('Row '+(index+2)+': '+msg)};const title=text(row,'Title');if(!title)fail('Title is required.');const rawWatched=text(row,'Episodes watched');const watched=rawWatched===''?0:Number(rawWatched);const rawTotal=text(row,'Total episodes'),flag=text(row,'Ongoing').toLowerCase();if(!['','yes','no','true','false','1','0'].includes(flag))fail('Ongoing must be Yes or No.');const ongoing=['yes','true','1'].includes(flag)||rawTotal==='';const total=ongoing?null:Number(rawTotal);const rawType=text(row,'Type')||'Series';const type=['Series','Anime','Movie'].find(t=>t.toLowerCase()===rawType.toLowerCase());const rawStatus=text(row,'Status')||'Watching';let status=statuses.slice(1).find(t=>t.toLowerCase()===rawStatus.toLowerCase());const updatedText=text(row,'Updated');const updated=updatedText?Date.parse(updatedText):Date.now();if(!Number.isFinite(updated))fail('Updated must be an ISO date/time, or blank.');const x={id:text(row,'ID')||crypto.randomUUID(),title,type,genre:text(row,'Genre'),watched,total,status,url:text(row,'URL'),notes:text(row,'Notes'),updated};if(!valid(x))fail('Check type, status, URL, and episode counts (whole numbers, watched cannot exceed total).');if(total!==null){if(status==='Completed')x.watched=total;else if(watched===total)x.status='Completed'}out.push(x)});if(out.length>10000)throw Error('Import up to 10,000 titles at a time.');return out}
function checkImport(data){if(!Array.isArray(data)||!data.every(valid))throw Error('Invalid title data or unsupported URL.');if(new Set(data.map(x=>x.id)).size!==data.length)throw Error('Duplicate IDs found. Each title needs a unique ID.');return data}
function readExcel(buffer){const wb=XLSX.read(buffer,{type:'array',cellDates:false,sheetRows:10002});const sheet=wb.Sheets[wb.SheetNames.includes('WatchLyst')?'WatchLyst':wb.SheetNames[0]];if(!sheet)throw Error('No worksheet found.');const ref=XLSX.utils.decode_range(sheet['!fullref']||sheet['!ref']||'A1');if(ref.e.r>10000||ref.e.c>100)throw Error('Use at most 10,000 titles and 101 columns.');for(const [key,cell] of Object.entries(sheet)){if(!key.startsWith('!')&&cell.f)throw Error('Use plain values instead of formulas in the WatchLyst sheet.')}return checkImport(parseExcelRows(XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true})))}
function mergeTitles(current,incoming){const result=current.map(x=>({...x}));for(const x of incoming){let at=result.findIndex(old=>old.id===x.id);if(at<0)at=result.findIndex(old=>old.title.toLowerCase().trim()===x.title.toLowerCase().trim()&&old.type===x.type);if(at<0)result.push({...x});else result[at]={...x,id:result[at].id}}return result}
let pendingImport=null;
$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('File must be smaller than 5 MB.');pendingImport=file.name.toLowerCase().endsWith('.json')?checkImport(JSON.parse(await file.text())):readExcel(await file.arrayBuffer());$('importSummary').textContent=pendingImport.length+' titles ready from '+file.name+'. Your current list has '+items.length+' titles.';$('importPreview').replaceChildren(...pendingImport.slice(0,30).map(x=>el('li','',x.title+' · '+x.watched+(x.total===null?' watched · Ongoing':' / '+x.total)+' · '+x.status)));$('mergeImport').disabled=pendingImport.length===0;$('importDialog').showModal()}catch(e){pendingImport=null;notify('Import failed: '+e.message)}finally{$('file').value=''}};
function applyImport(mode){if(!pendingImport)return;if(mode==='replace'&&!confirm('Replace all '+items.length+' existing titles with '+pendingImport.length+' imported titles?'))return;const next=mode==='merge'?mergeTitles(items,pendingImport):pendingImport;items=next;const saved=save();pendingImport=null;$('importDialog').close();render();notify(saved?'Import saved: '+items.length+' titles':'Imported for this session — export a backup')}
$('mergeImport').onclick=()=>applyImport('merge');$('replaceImport').onclick=()=>applyImport('replace');$('cancelImport').onclick=()=>{pendingImport=null;$('importDialog').close()};
